class AdjacentSetupDrop:
    """Elimina un setup redundante en t si el ítem ya se preparó en t-1.
    Movimiento = (i, t).
    """

    def __init__(self, problem):
        self.problem = problem

    def moves(self, sol):
        inst = self.problem.inst
        for i in range(inst.n_items):
