        return tuple(
            tuple((val if tt != t or ii != i else True) for tt, val in enumerate(row))
            for ii, row in enumerate(sol)
        )

    def delta(self, sol, m):
        return self.problem.objective(self.apply(sol, m)) - self.problem.objective(sol)


